TITLE = "Quantum-Optimised Generation of Operational Design Domain Boundary Test Scenarios, Traceably Derived from Safety Requirements for Automated Driving Systems"

B = []
A = B.append

# ---------------- Front matter ----------------
A(('title', TITLE))
A(('meta', "Saadia Sadaf (SP24-PCS-002)"))
A(('meta', "Doctor of Philosophy in Computer Science"))
A(('meta', "Department of Computer Science, COMSATS University Islamabad"))
A(('meta', "Supervisor: Prof. Dr. Manzoor Ilahi Tamimy"))
A(('meta', "Co-supervisor: Prof. Dr. Majid Iqbal Khan"))
